#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>


int main(void) {
int a[256]; int n;
if (scanf("%d", &n)!=1 || n<0 || n>256) return 1;
for(int i=0;i<n;++i) if(scanf("%d", &a[i])!=1) return 1;
int d;if(scanf("%d",&d)!=1)return 1;long long pairs=0;for(int i=0;i<n;++i)for(int j=i+1;j<n;++j)if(abs(a[i]-a[j])<=d)++pairs;printf("%lld\n",pairs);
return 0;
}
